\label{def:uas}
A randomized algorithm $\mathcal{A}:\ensuremath{\mathcal{X}}^n\mapsto\mathcal{W}\times\Theta$ satisfies $\Delta$-uniform argument stability (UAS) if for any pair of adjacent datasets $S,S'\in\ensuremath{\mathcal{X}}^n$ it holds that  
$\underset{\mathcal{A}}{\mathbb{E}}\left[ \left\|\mathcal{A}(S)-\mathcal{A}(S')\right\| \right] \leq \Delta$.

\label{lem:sc-ssp-stability}
Let $\psi:\mathcal{W}\times\Theta\mapsto\mathbb{R}$ be $\mu$-strongly-convex/strongly-concave w.r.t. $\|\cdot\|_w$ and $\|\cdot\|_\theta$. Then the algorithm which returns the saddle point of 
$(w,\theta) \mapsto \frac{1}{n}\sum_{z\in S} f(w,\theta;z) + \psi(w,\theta)$ is $(\frac{2L}{\mu n})$-UAS.

\label{asm:weak-alg}
Given a dataset $S'\in\ensuremath{\mathcal{X}}^{n'}$, loss function $f'$, and an initial point $[w',\theta'],$ we say that $\mathcal{A}_{\mathsf{sub}}$ satisfies $\hat{\alpha}$-relative accuracy w.r.t.~the empirical saddle point $[w_{S'}^*, \theta_{S'}^*]$ of $F'_{S'}(w,\theta)=\frac{1}{n'}\sum_{x\in {S'}}f'(w,\theta;x)$ 
if, $\forall \hat{D}>0$, whenever $\underset{}{\mathbb{E}}\left[ \left\|[w',\theta'] - [w^*_{S'},\theta^*_{S'}]\right\| \right] \leq \hat{D}$, the output $[\bar{w},\bar{\theta}]$ of $\mathcal{A}_{\mathsf{sub}}$ satisfies $\underset{}{\mathbb{E}}\left[ F'_{S'}(\bar{w},\theta^*_{S'})- F'_{S'}(w^*_{S'},\bar{\theta}) \right] \leq \hat{D}\hat{\alpha}$.

\label{lem:ra-stab-gen}
Let $f:\ensuremath{\mathcal{Z}}\times\ensuremath{\mathcal{X}}\mapsto \mathbb{R}$ be $L$-Lipschitz. Let $[w^*,\theta^*]\in\ensuremath{\mathcal{Z}}$ be the population saddle point. For any $x\in\ensuremath{\mathcal{X}}$ define $h([w,\theta];x)=f(w,\theta^*;x) - f(w^*,\theta;x)$. For $S\sim \mathcal{D}^n$, let $H_S(z) = \frac{1}{n}\sum_{x\in S} h(z;x)$ and $H_\mathcal{D}(z) = \underset{x\sim\mathcal{D}}{\mathbb{E}}\left[ h(z;x) \right]$. Then for any $\Delta$-UAS algorithm, $\mathcal{A}$, one has
$\underset{S,A}{\mathbb{E}}\left[ H_\mathcal{D}(\mathcal{A}(S))-H_S(\mathcal{A}(S)) \right] \leq 2\Delta L$.

\label{thm:recursive-regularization-vi}
Let $\mathcal{A}_{\mathsf{sub}}$ satisfy $\hat{\alpha}$-relative stationarity for any 
$(5L)$-bounded monotone operator and dataset of size $n'=\frac{n}{\log(n)}$. Let $\rho$ satisfy Assumption \ref{assm:operator}.
Then 
Algorithm~\ref{alg:recursive-regularization}, 
run with $\mathcal{A}_{\mathsf{sub}}$ as a subroutine and $\lambda=\frac{48}{B}\left({\hat{\alpha}\kappa^3 + \frac{(\betaB+L)\kappa^2}{\sqrt{n'}}}\right)$,  
satisfies 
\begin{align*}
    \operatorname{VI-Gap}(\mathcal{R}_{\text{SVI}}) = O\Big(\log(n)B\hat{\alpha}\kappa^3 + \frac{\log^{3/2}(n)B(\betaB+L)\kappa^2}{\sqrt{n}}\Big).
\end{align*}

\label{def:rel-acc}
Given a dataset $S'\in\ensuremath{\mathcal{X}}^{n'}$, operator $g'$, and an initial point $z'$, we say that $\mathcal{A}_{\mathsf{sub}}$ satisfies $\hat{\alpha}$-relative stationarity w.r.t. to the empirical equilibrium $z^*_{S'}$ of $G_{S'}(z)=\frac{1}{n'}\sum_{x\in S'}g'(z;x)$,  
if, $\forall \hat{D}>0$, whenever $\underset{}{\mathbb{E}}\left[ \left\|z' - z^*_{S'}\right\| \right] \leq \hat{D}$, the output $\bar{z}$ of $\mathcal{A}_{\mathsf{sub}}$ satisfies          \linebreak           $\underset{}{\mathbb{E}}\left[ \left\langle G(\bar z),\bar z-z^*_{S'} \right\rangle \right] \leq \hat{D}\hat{\alpha}$.

There exists an Algorithm, $\mathcal{R}$, which is $(\epsilon,\delta)$-DP, has gradient evaluations bounded by          \linebreak     $O\big(\min\big\{\frac{\sqrt{\kappa}n^2\epsilon^{1.5}}{\log(n)\sqrt{d\log(1/\delta)\tilde{\kappa}}}, \frac{\sqrt{\kappa}n^{3/2}}{\sqrt{\log(n)}}\big\}\big)$,  
and satisfies (up to $\log(n)$ factors)
\begin{align} \label{eq:main-svi-result}
    \operatorname{VI-Gap}(\mathcal{R}) = \tilde{O}\Big(\kappa^{3.5}BL\big(\frac{\sqrt{d\log(1/\delta)\tilde{\kappa}}}{n\epsilon} + \frac{1}{\sqrt{n}}\big)\Big).
\end{align}
where $\kappa = \frac{1}{\max\left\{{p,1+\frac{1}{\log(d)}}\right\}-1}$ is at most $\log(d)$ and $\tilde{\kappa} = 1+\mathbf{1}\left\{{p<2}\right\}\cdot\log(d)$.

\label{thm:generalized-rr-convergence}
Let $\lambda \geq \frac{48L\kappa^{3/2}}{B\sqrt{n'}}$
and $\mathcal{A}_{\mathsf{sub}}$ be such that for all $t\in [T]$ it holds that                            $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right] \leq \frac{B^2}{12\cdot2^{2t}\kappa^{3/2}}$.
Then Recursive Regularization satisfies
\begin{align*}
    \operatorname{Gap_{\mathsf{SP}}}(\mathcal{R}_{\text{SSP}}) = O\Big(\log(n)B^2\lambda\Big).
\end{align*}

\label{fact:rel-acc-bounds-distance}
Let $F:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}^d$ be a $\gamma$-SC/SC function and let $[w^*,\theta^*]$ be the saddle point. Then 
$\|[w,\theta]-[w^*,\theta^*]\|^2 \leq \frac{2\left({F(w,\theta^*)-F(\theta^*,w)}\right)}{\lambda}$.

\label{lem:phase-distance-bound}
Assume the conditions of Theorem \ref{thm:generalized-rr-convergence} hold. Then for every $t\in[T]$, the following holds
\begin{enumerate}[label=\textbf{P.\arabic*}]
    \item $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\|^2 \right] \leq \frac{B^2}{2^{2t}\kappa}$; and, \label{prop:p1}
    \item $B_t^2 := \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}]\right\|^2 \right] \leq \frac{B^2}{2^{2(t-1)}}$. \label{prop:p2}
\end{enumerate}

We will prove both properties via induction on $B_1,...,B_T$. Specifically, for each $t\in[T]$ we will introduce two terms $E_t$ and $F_t,$, and show that 
these terms are bounded 
if the bound on $B_{t}$ holds and that $B_t$ holds if
$E_{t-1}$ and $F_{t-1}$ are bounded. 
Property \ref{prop:p1} is then established as a result of the fact that $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\|^2 \right] \leq 2(E_t+F_t)$.
Note that $B_1$ holds as the base case because 
$\underset{}{\mathbb{E}}\left[ \left\|z_{1}^* - z_0^*\right\|^2 \right] \leq B^2$.

\paragraph{Property \ref{prop:p1}:} 
We here prove that if $B_t$ is sufficiently bounded, then $E_t$ and $F_t$ are bounded where 
for $t\in [T]$ we define
\begin{align} \label{eq:EF}
    E_t = \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right],
    && F_t = \frac{\kappa}{2^t\lambda}\underset{}{\mathbb{E}}\left[ H_\mathcal{D}^{(t)}\left({z^*_{S,t}}\right) \right].
\end{align}
Additionally, this will establish property \ref{prop:p1} because for any $t\in[T]$ it holds that, 
\begin{align}
    \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\|^2 \right] \nonumber 
    &\leq  2\Bigg(\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right] + \underset{}{\mathbb{E}}\left[ \left\|z^*_{S,t} - z^*_{t}\right\|^2 \right]\Bigg) \nonumber \\
    &\leq  2\Bigg(\underbrace{\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right]}_{E_t} + \underbrace{\frac{\kappa}{2^t\lambda}\underset{}{\mathbb{E}}\left[ H_\mathcal{D}^{(t)}\left({z^*_{S,t}}\right) \right]}_{F_t}\Bigg). \label{eq:E-F-G}
\end{align}
The second inequality comes from the strong monotonicity of the operator (see Fact \ref{fact:rel-acc-bounds-distance}). 

Note that $E_t$ is bounded  by the assumption made in the statement of the theorem statement. We thus turn our attention towards bounding $F_t$. 
We have 
\begin{align*}
    \frac{\kappa}{2^t\lambda}\underset{}{\mathbb{E}}\left[ H_\mathcal{D}^{(t)}\left({z^*_{S,t}}\right) \right]
    &= \frac{\kappa}{2^t\lambda}\,\,\underset{}{\mathbb{E}}\left[ \underset{}{\mathbb{E}}\left[ H_\mathcal{D}^{(t)}\left({z^*_{S,t}}\right) \Big| \mathcal{F}_{t-1} \right] \right] \\
    &\overset{(i)}{\leq}  \frac{\kappa}{2^{t}\lambda}\Big(\underset{}{\mathbb{E}}\left[ \underset{}{\mathbb{E}}\left[ H_S^{(t)}\left({z^*_{S,t}}\right)\Big| \mathcal{F}_{t-1} \right] \right]+\frac{\kappaL^2}{2^t\lambda n'}\Big) \\
    &= \frac{\kappa}{2^{t}\lambda}\Big(\underset{}{\mathbb{E}}\left[ \underset{}{\mathbb{E}}\left[ F_S^{(t)}(w_{S,t}^*,\theta_t^*)-F_S^{(t)}(w_t^*,\theta_{S,t}^*)\Big| \mathcal{F}_{t-1} \right] \right]+\frac{2\kappaL^2}{2^t\lambda n'}\Big) \\
    &\overset{(ii)}{=} \frac{2\kappa^2L^2}{2^{2t}\lambda^2 n'} 
    \leq \frac{B^2}{1152 \cdot 2^{2t}\kappa}. 
\end{align*}
Inqeuality $(i)$ comes from the fact that stability implies generalization for $H^{(t)}$, Lemma \ref{lem:ra-stab-gen}. Note the algorithm which outputs this exact equilibrium point is $\frac{L^2}{2^t\lambda n'}$ stable (see Lemma \ref{lem:sc-op-stability}/Assumption \ref{assm:operator}).
Step $(ii)$ uses the fact that $z^*_{S,t}$ is the exact saddle point of the regularized objective, and so for any $[w,\theta]\in\ensuremath{\mathcal{Z}}$, $F_S^{(t)}(w_{S,t}^*,\theta)-F_S^{(t)}(w,\theta_{S,t}^*) \leq 0$. The final inequality uses the setting of $\lambda$.

We thus have a final bound $2(E_t + F_t) \leq \frac{B^2}{2^{2t}}$.

\paragraph{Property \ref{prop:p2}:}
Now assume $B_{t-1}$ holds. 
We have 

\begin{align}
    \underset{}{\mathbb{E}}\left[ \left\|z^*_{t} - z^*_{t-1}\right\|^2 \right] 
    &\leq \underset{}{\mathbb{E}}\left[ \frac{\kappa}{2^t \lambda}H_{\mathcal{D}}^{(t)}(z^*_{t-1}) \right] \nonumber \\
    &= \underset{}{\mathbb{E}}\left[ \frac{\kappa}{2^t \lambda}\left({F_{\mathcal{D}}^{(t)}(w_{t-1}^*,\theta_t^*) - F_{\mathcal{D}}^{(t-1)}(w_{t}^*,\theta_{t-1}^*)}\right) \right] \nonumber \\
    &= \mathbb{E}\Big[\frac{\kappa}{2^t \lambda}\left({F_{\mathcal{D}}^{(t-1)}(w_{t-1}^*,\theta_t^*) - F_{\mathcal{D}}^{(t-1)}(w_{t}^*,\theta_{t-1}^*)}\right) \nonumber \\
    &\quad + \kappa\left({\|w^*_{t-1}-\bar{w}_{t-1}\|_w^2 - \|\theta_t^* - \bar{\theta}_{t-1}\|_\theta^2 - \|w^*_{t}-\bar{w}_{t-1}\|_w^2 + \|\theta_t^* - \bar{\theta}_{t-1}\|_\theta^2}\right)\Big] \nonumber \\
    &\overset{(i)}{\leq} \underset{}{\mathbb{E}}\left[ \kappa\|z^*_{t-1}-\bar{z}_{t-1}\|^2  \right] \label{eq:p2-derivation-ssp}
\end{align} 
Inequality $(i)$ above comes from removing negative terms and the fact that $z^*_{t-1}$ is the saddle point w.r.t. $F_{\mathcal{D}}^{(t-1)}$. 
Using the induction argument we then complete the bound with the following:
\begin{align*}
 \underset{}{\mathbb{E}}\left[ \left\|z^*_{t} - z^*_{t-1}\right\|^2 \right] \leq \underset{}{\mathbb{E}}\left[ \kappa\|z^*_{t-1}-\bar{z}_{t-1}\|^2 \right]  
 \leq \kappa(E_{t-1} + F_{t-1}) \leq \frac{B^2}{2^{2t}}
\end{align*}

Using the fact that $\widehat{\operatorname{Gap}}_{\mathsf{SP}}$ is $\sqrt{2}L$-Lipschitz and property \ref{prop:p1}, we have 
\begin{align}
    \underset{}{\mathbb{E}}\left[ \widehat{\operatorname{Gap}}_{\mathsf{SP}}(\bar{z}_T) - \widehat{\operatorname{Gap}}_{\mathsf{SP}}(z_{T}^*) \right] 
    &\leq  \sqrt{2}L\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_T - z_{T}^*\right\| \right] \nonumber \\
    &\leq \frac{\sqrt{2}BL}{2^T}
    \leq \sqrt{2}B^2\lambda. \label{eq:error-to-final-min}
\end{align}

What remains is showing $\underset{}{\mathbb{E}}\left[ \widehat{\operatorname{Gap}}_{\mathsf{SP}}(w_{T}^*,\theta_{T}^*) \right]$ is $\tilde{O}(B\hat{\alpha} + \frac{BL}{\sqrt{n'}})$. Let $w' = \operatorname*{arg\,min}\limits_{\theta\in\Theta}{F_{\mathcal{D}}(w,\theta_T^*)}$ and $\theta' = \operatorname*{arg\,max}\limits_{w\in\mathcal{W}}{F_{\mathcal{D}}(w_T^*,\theta})$. 
Using the fact that $F_{\mathcal{D}}$ is convex-concave we have 
\begin{align}
    \widehat{\operatorname{Gap}}_{\mathsf{SP}}(w^*_T,\theta^*_T) = F_{\mathcal{D}}(w_T^*,\theta') - F_{\mathcal{D}}(w',\theta_T^*)
    &\leq \left\langle G_{\mathcal{D}}(w_T^*,\theta_T^*),[w^*_T,\theta^*_T] - [w',\theta'] \right\rangle \label{eq:gap-grad-bound} 
\end{align}
         \vfill \noindent     where $G_{\mathcal{D}}$ is the population loss saddle operator.
Further by the definition of $F^{(T)}$ and denoting $G_{\mathcal{D}}^{(T)}$ as the saddle operator for $F_{\mathcal{D}}^{(T)}$ we have
\begin{align*}
    G_{\mathcal{D}}(w_{T}^*,\theta_{T}^*)
    &= G_{\mathcal{D}}^{(T)}(w_{T}^*,\theta_{T}^*) - 2\lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\nabla(\|[w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\|^2) 
\end{align*}
         \vfill \noindent    
Thus plugging the above into Eqn. \eqref{eq:gap-grad-bound} we have
         \vfill    
\begin{align*}
   \widehat{\operatorname{Gap}}_{\mathsf{SP}}(w^*_T,\theta^*_T) &\leq  
   \left\langle G_{\mathcal{D}}^{(T)}(w_{T}^*,\theta_{T}^*),[w^*_T,\theta^*_T] - [w',\theta'] \right\rangle \\
   &\textstyle\quad- \left\langle 2\lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\nabla(\|w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\|^2),[w^*_T,\theta^*_T] - [w',\theta'] \right\rangle \\
   &\textstyle\leq - \left\langle 2\lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\nabla(\|w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\|^2),[w^*_T,\theta^*_T] - [w',\theta'] \right\rangle \\
   &\textstyle\leq 2B \lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\left\|\nabla(\|w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\|^2)\right\|_* \\
   &\textstyle\leq 2B \lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\left\|[w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\right\|.
\end{align*}
         \vfill \noindent    
Above, the second inequality comes from the first order optimally conditions for $[w_T^*,\theta_T^*]$, the third from Cauchy Schwartz and a triangle inequality. The last inequality comes from the relationship between a norm and its dual, see Fact \ref{fact:grad-dual-relation}.

Taking the expectation on both sides of the above we have the following derivation,
{\small
\begin{align}
    &\underset{}{\mathbb{E}}\left[ \widehat{\operatorname{Gap}}_{\mathsf{SP}}(w_{T}^*,\theta_{T}^*) \right] 
    \leq 2B\underset{}{\mathbb{E}}\left[ \lambda \sum\limits_{t=0}^{T-1} 2^{t+1}\left\|[w_{T}^*,\theta_{T}^*] - [\bar{w}_t,\bar{\theta}_t]\right\| \right] \nonumber \\
    &\overset{(i)}{\leq} 4B\underset{}{\mathbb{E}}\left[ \lambda \sum\limits_{t=0}^{T-1} 2^{t} \left({\left\|[w_{t}^*,\theta_{t}^*] - [\bar{w}_t,\bar{\theta}_t]\right\| + \sum\limits_{r=t}^{T-1}\left\|[w_{r+1}^*,\theta_{r+1}^*]  - [w_{r}^*,\theta_{r}^*]\right\|}\right) \right] \nonumber \\
    &= 4B\underset{}{\mathbb{E}}\left[ \lambda \sum\limits_{t=0}^{T-1} 2^{t} \left\|[w_{t}^*,\theta_{t}^*] - [\bar{w}_t,\bar{\theta}_t]\right\| + \lambda\sum\limits_{t=0}^{T-1} 2^{t}\sum\limits_{r=t}^{T-1} \left\|[w_{r+1}^*,\theta_{r+1}^*]  - [w_{r}^*,\theta_{r}^*]\right\| \right] \nonumber \\
    &\overset{(ii)}{=} 4B\underset{}{\mathbb{E}}\left[ \lambda \sum\limits_{t=0}^{T-1} 2^{t} \left\|[w_{t}^*,\theta_{t}^*] - [\bar{w}_t,\bar{\theta}_t]\right\| + \lambda\sum\limits_{r=0}^{T-1}\sum\limits_{t=0}^{r-1} 2^{t} \left\|[w_{r+1}^*,\theta_{r+1}^*]  - [w_{r}^*,\theta_{r}^*]\right\| \right] \nonumber \\
    &= 4B\underset{}{\mathbb{E}}\left[ \lambda \sum\limits_{t=0}^{T-1} 2^{t} \left\|[w_{t}^*,\theta_{t}^*] - [\bar{w}_t,\bar{\theta}_t]\right\| + \lambda\sum\limits_{r=0}^{T-1}\left\|[w_{r+1}^*,\theta_{r+1}^*]  - [w_{r}^*,\theta_{r}^*]\right\|\sum\limits_{t=0}^{r-1} 2^{t} \right] \nonumber \\
    &\overset{(iii)}{\leq} 4B\left({\lambda \sum\limits_{t=0}^{T-1} 2^{t}\left({\frac{B}{2^{t}}}\right) + \lambda\sum\limits_{r=1}^{T-1}\left({\frac{B
    }{2^{r}}}\right)\sum\limits_{t=0}^{r-1} 2^{t}}\right) \nonumber \\
    &\leq 4B\left({ \lambda \sum\limits_{t=0}^{T-1} 2^{t}\left({\frac{B}{2^{t}}}\right) + \lambda\sum\limits_{r=1}^{T-1}\left({\frac{B}{2^{r-1}}  }\right)\cdot (2^{r}-1)}\right) \nonumber \\
    &= 4\lambda \sum\limits_{t=0}^{T-1} B^2 + 8\lambda\sum\limits_{r=1}^{T-1} B^2 \nonumber \\
    &\leq 12T \lambda B^2 
    \label{eq:final-gap-bound}
\end{align}}
Above, $(i)$ and the following inequality both come from the triangle inequality. Equality $(ii)$ is obtained by rearranging the sums. Inequality $(iii)$  
comes from applying properties \ref{prop:p1} and \ref{prop:p2} proved above. The last equality comes from the setting of $\lambda$ and $T$.

Now using this result in conjunction with Eqn. \eqref{eq:error-to-final-min} 
we have
\begin{align*}
    \operatorname{Gap_{\mathsf{SP}}}(\mathcal{R}) = \sqrt{2}\lambdaB^2 + 12T\lambdaB^2 = O\left({\log(n)B^2\lambda}\right).
\end{align*}
Above we use the fact that $T=\log(\frac{L}{B\lambda})$ and $\lambda \geq \frac{L}{B\sqrt{n'}}$, and thus $T=O(\log(n))$.

First, observe that under the setting of $\lambda=\frac{48}{B}\left({\hat{\alpha}\kappa^2 + \frac{L \kappa^{3/2}}{\sqrt{n'}}}\right)$ used in the theorem statement that $\log(n)B^2\lambda = O\left({\log(n)B\hat{\alpha}\kappa^2 + \frac{\log^{3/2}(n)BL\kappa^{3/2}}{\sqrt{n}}}\right)$. Thus what remains is to show that the distance condition required by Theorem \ref{thm:generalized-rr-convergence} holds. That is, we now show that if $\mathcal{A}_{\mathsf{sub}}$ satisfies $\hat{\alpha}$-relative accuracy, then 
for all $t\in [T]$ it holds that $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right] \leq \frac{B^2}{12\cdot2^{2t} \kappa}$.

To prove this property, we must leverage the induction argument made by Lemma \ref{lem:phase-distance-bound}. Specifically, to prove the condition holds for some $t\in[T]$, assume 
$B_t^2 = \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}]\right\| \right]^2 \leq \frac{B^2}{2^{2(t-1)}}$ (recall the base case for $t=1$ trivially holds). As shown in the proof of Lemma \ref{lem:phase-distance-bound}, this implies that the quantities
$E_t,F_t$ (as defined in \ref{eq:EF}) are bounded by $\frac{B^2}{1152 \cdot 2^{2t}}$. We thus have
\begin{align} \label{eq:Et-bound-relative-acc}
    \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right]
    &\overset{(i)}{\leq} \frac{\kappa \underset{}{\mathbb{E}}\left[ F_S^{(t)}(\bar{w}_t,\theta_{S,t}^*)-F_S^{(t)}(w_{S,t}^*,\bar{\theta}_t) \right]}{2^{t}\lambda} 
    \overset{(ii)}{\leq} \frac{2\kappa \hat{\alpha}B}{2^{2t}\lambda} 
    \overset{(iii)}{\leq} \frac{B^2}{12 \cdot 2^{2t} \kappa},
\end{align}
where $B_t$ is as defined in property \ref{prop:p2}.
Inequality $(i)$ comes from the strong monotonicity of $G_S^{(t)}$, Fact \ref{fact:rel-acc-bounds-distance}.
Inequality $(iii)$ comes from the setting $\lambda \geq 48\hat{\alpha}\kappa^2/B$.
Inequality $(ii)$ comes from the $\hat{\alpha}$-relative accuracy assumption on $\mathcal{A}_{\mathsf{sub}}$, which holds so long as the expected distance is sufficiently bounded and each regularized loss is ($5L$)-Lipschitz. In this regard, note that
\begin{align*}
    \underset{}{\mathbb{E}}\left[ \|z^*_{S,t}-\bar{z}_{t-1}\| \right] &\leq  \underset{}{\mathbb{E}}\left[ \|z^*_{S,t}-z^*_t\|+\|z^*_t-z^*_{t-1}\|+\|z^*_{t-1}-\bar{z}_{t-1}\| \right] \\
    &\leq (\sqrt{F_t}+B_t+\sqrt{E_{t-1}}+\sqrt{F_{t-1}}) \leq \frac{B}{2^t}.
\end{align*}
Further, each $f^{(t)}$ is $5L$-Lipschitz. We can see that,
\begin{align*}    
\max\limits_{z\in\ensuremath{\mathcal{Z}}}\|\nabla f^{(t)}(z,x)\|_* 
\leq L + \|\sum_{k=0}^{t-1} 2^{k+1}\lambda \nabla(\|z-\bar{z}_t\|^2)\|_* 
 \leq L + \sum_{k=0}^{t-1}B 2^{k+1}\lambda\leq L + 4B 2^{T}\lambda \leq 5L.
\end{align*}

\label{lem:mirror-prox-bound}
Let $\psi:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}$ be any non-negative function which is $1$-strongly convex w.r.t. $\|\cdot\|$.
Assume $\forall t\in[T]$ that $\underset{}{\mathbb{E}}\left[ \ensuremath{\mathcal{O}}(z_t) \right]=G(z_t)$ and $\underset{}{\mathbb{E}}\left[ \|\ensuremath{\mathcal{O}}(z_t) - G(z_t)\|_*^2 \right] \leq \tau^2$. Then for for any $z\in\ensuremath{\mathcal{Z}}$ Algorithm \ref{alg:mirror-prox} satisfies
\begin{align*}
    \underset{}{\mathbb{E}}\left[ \frac{1}{T}\sum_{t=1}^T\left\langle G(z_t),z_t-z \right\rangle \right] = O\left({\frac{\underset{}{\mathbb{E}}\left[ \psi(z) \right]}{T\eta} + \frac{7\eta}{2}(L^2 + 2\tau^2)}\right).
\end{align*}

\label{thm:noisy-mirror-prox}
Let $[w_0,\theta_0],[w,\theta]$ satisfy $\underset{}{\mathbb{E}}\left[ \|[w_0,\theta_0]-[w,\theta]\| \right] \leq \hat{D}$. Let $g:\mathcal{W}\times\Theta \times \ensuremath{\mathcal{X}} \mapsto \mathcal{B}^{d_w}_{\|\cdot\|_{\bar{p}}}(B_w L_w)\times\mathcal{B}^{d_\theta}_{\|\cdot\|_{\bar{q}}}(B_\theta L_\theta)$ be a monotone operator and $G_S(w,\theta)=\frac{1}{n}\sum_{x\in S} g([w,\theta];x)$.
There exists an implementation of 
$\ensuremath{\mathcal{O}}$ such that Algorithm \ref{alg:mirror-prox} is $(\epsilon,\delta)$-DP and the following holds
\begin{align*}
    &\underset{}{\mathbb{E}}\left[ \left\langle G_S([w_{t^*},\theta_{t^*}]),[w_{t^*},\theta_{t^*}]-[w,\theta] \right\rangle \right] = \underset{}{\mathbb{E}}\left[ \frac{1}{T}\sum_{t=1}^T\left\langle G_S([w_t,\theta_t]),[w_t,\theta_t]-[w,\theta] \right\rangle \right] \\
    &\quad = O\left({\hat{D}\sqrt{B_w^2L_w^2+B_\theta^2L_\theta^2}\left({\frac{\sqrt{\kappa}\sqrt{d\log(1/\delta)\tilde{\kappa}}}{n\epsilon} + \frac{\sqrt{\kappa}}{\sqrt{n}}}\right)}\right)
\end{align*}
Further, the resulting algorithm makes $O\big(\min\big\{\frac{\sqrt{\kappa}n^2\epsilon^{1.5}}{\log^2(n)\sqrt{d\log(1/\delta)\tilde{\kappa}}}, \frac{\sqrt{\kappa}n^{3/2}}{\log^{3/2}(n)}\big\}\big)$ gradient evaluations.

To obtain Lemma \ref{lem:dp-mirror-prox-rel-acc} from this statement, observe that in the special case where $g$ is the saddle operator of the loss, $f$, convexity-concavity implies 
